INSERT INTO "strategies" ("id", "slug", "name", "description", "kind", "status", "source_ref", "tags", "section", "params") VALUES
  ('strategy-seed-market-intraday-momentum', 'market-intraday-momentum', 'Market intraday momentum: GHLZ, ZAB and bias tracker (reel)', 'Long and short, flat at the 16:00 close (Instagram reel DffkN31PrN7). GHLZ (Gao, Han, Li & Zhou 2018): at 15:30 New York go long if the return from the previous close to 10:00 is positive, short if negative. ZAB (Zarattini, Aziz & Barbon 2024): every half hour from 10:00 to 15:30 go long above the 14-day noise band, short below it, exit back through the band or VWAP, volatility-target sizing at most 4x. BIAS: a reconstructed 8-factor bias score (long at +50, short at -50 at 15:30). Tested on Nautilus with 5-minute bars on the Core 7 futures proxies and ETF twins in two forms: as stated on the underlying, and as same-day debit verticals on the ETF twin sized at 2% max loss. Results, walk-forward and robustness are in the backtest study (research_studies id market-intraday-momentum, Backtests tab). Research only (no orders).', 'python', 'backtested', 'docs/specs/strategies/market-intraday-momentum.md', '["research-only","backtest-study","reel-idea","intraday","momentum","long-short","options","defined-risk"]'::jsonb, 'Reel ideas', '[]'::jsonb)
